mapper.select:
        SELECT
            vch.*,
            vcg.id as group_id,
            vcg.name as group_name,
            vp.id as panel_id,
            vp.name as panel_name,
            case when vch.var_type=1 then aa.name when vch.var_type=2 then me.name end as var_name
        FROM visual_chart vch
        left join visual_chart vcg on vch.group_id = vcg.id
		left join visual_panel vp on vch.panel_id = vp.id
		left join asset_asset aa on vch.var_id = aa.id 
		left join monitor_endpoint me on vch.var_id = me.id 
        WHERE 1=1

            and vch.id in 

	       		#{id}




            AND vch.panel_id = #{params.panelId}



            AND vch.name LIKE CONCAT('%', #{params.name}, '%')



            AND vch.type = #{params.type}



            AND vch.pid in 

		       		#{pid}




            AND vch.var_type = #{params.varType}



			AND vch.group_id = #{params.groupId}



			AND vch.group_id in 

		       		#{gid}




			AND vp.type = #{params.panelType}


        /* 如果排序字段为null , 按照 weight 排序 */

            ORDER BY vch.weight,vch.id

mapper.update:
UPDATE visual_chart

       span = #{chart.span},
       height = #{chart.height}

WHERE
        id = #{chart.id}

mapper.select:
	select vch.*
	from visual_chart vch 

		left join asset_asset aa on vch.var_id = aa.id


		left join monitor_endpoint me on vch.var_id = me.id 

	where vch.pid is not null 

		and vch.panel_id = #{params.panelId} 


		and vch.pid = #{params.pid}


		and vch.id in

       		#{id}

select vc.* from visual_chart vc
left join asset_asset t on vc.var_id = t.id
left join monitor_endpoint t on vc.var_id = t.id
where 1=1
and t.model_id = #{id}
and t.module_id= #{id}

SELECT vch.*, vce.id AS vce_id, vce.expression AS vce_expression, vce.type AS vce_type, vce.legend AS vce_legend FROM visual_chart vch LEFT JOIN visual_chart_element vce ON vch.id = vce.chart_id
vch.id in
#{id}
